-- Fase 8: Plan de Pan. Stripe Billing é autoridade financeira; FUERZA é autoridade operacional e de capacidade.
create type public.subscription_plan_status as enum('draft','active','hidden','archived');
create type public.subscription_frequency as enum('weekly','biweekly','monthly');
create type public.subscription_status as enum('incomplete','trialing','active','past_due','paused','cancel_pending','cancelled','unpaid','requires_attention');
create type public.subscription_cycle_status as enum('planned','capacity_reserved','invoiced','paid','order_created','skipped','failed','cancelled');
create type public.subscription_change_type as enum('pause','resume','cancel','change_plan','change_pickup_point','change_weekday');
create type public.subscription_change_status as enum('pending','applied','rejected','cancelled');

create table public.subscription_plans(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text,status public.subscription_plan_status not null default 'draft',billing_interval public.subscription_frequency not null,billing_interval_count integer not null check(billing_interval_count in(1,2)),price_cents integer not null check(price_cents>=0),currency text not null default 'EUR' check(currency='EUR'),display_order integer not null default 0 check(display_order>=0),is_public boolean not null default false,stripe_product_id text,stripe_price_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_plan_items(id uuid primary key default gen_random_uuid(),subscription_plan_id uuid not null references public.subscription_plans(id) on delete cascade,product_variant_id uuid not null references public.product_variants(id) on delete restrict,quantity integer not null check(quantity>0),display_order integer not null default 0 check(display_order>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(subscription_plan_id,product_variant_id));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),customer_id uuid not null references auth.users(id) on delete restrict,subscription_plan_id uuid not null references public.subscription_plans(id) on delete restrict,pickup_point_id uuid not null references public.pickup_points(id) on delete restrict,preferred_weekday integer not null check(preferred_weekday between 1 and 7),preferred_collection_window_id uuid references public.pickup_point_collection_windows(id) on delete set null,status public.subscription_status not null default 'incomplete',stripe_customer_id text,stripe_subscription_id text unique,stripe_price_id text,current_period_start timestamptz,current_period_end timestamptz,next_collection_date date,paused_at timestamptz,pause_until date,cancel_at_period_end boolean not null default false,cancelled_at timestamptz,cancellation_reason text,requires_attention_reason text,internal_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.subscription_items(id uuid primary key default gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id) on delete cascade,product_variant_id uuid not null references public.product_variants(id) on delete restrict,product_name_snapshot text not null,variant_name_snapshot text not null,quantity integer not null check(quantity>0),unit_price_cents_snapshot integer not null check(unit_price_cents_snapshot>=0),vat_rate_snapshot numeric(5,2) not null,created_at timestamptz not null default now(),unique(subscription_id,product_variant_id));
create table public.subscription_cycles(id uuid primary key default gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id) on delete cascade,cycle_start date not null,cycle_end date not null,collection_date date not null,status public.subscription_cycle_status not null default 'planned',stripe_invoice_id text unique,stripe_payment_intent_id text,order_id uuid unique references public.orders(id) on delete set null,capacity_reserved boolean not null default false,failure_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(subscription_id,collection_date));
create table public.subscription_status_history(id uuid primary key default gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id) on delete cascade,previous_status public.subscription_status,new_status public.subscription_status not null,actor_id uuid references auth.users(id) on delete set null,source public.order_event_source not null,reason text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.subscription_change_requests(id uuid primary key default gen_random_uuid(),subscription_id uuid not null references public.subscriptions(id) on delete cascade,type public.subscription_change_type not null,requested_data jsonb not null default '{}'::jsonb,effective_from date not null,status public.subscription_change_status not null default 'pending',requested_by uuid not null references auth.users(id),processed_at timestamptz,created_at timestamptz not null default now());
alter table public.subscription_capacity_allocations add column subscription_cycle_id uuid unique references public.subscription_cycles(id) on delete cascade;
alter table public.orders add column order_type text not null default 'one_off' check(order_type in('one_off','subscription')),add column subscription_id uuid references public.subscriptions(id),add column subscription_cycle_id uuid unique references public.subscription_cycles(id);

create index subscriptions_customer_idx on public.subscriptions(customer_id,status);create index subscriptions_attention_idx on public.subscriptions(status) where status='requires_attention';create index cycles_due_idx on public.subscription_cycles(collection_date,status);create index changes_pending_idx on public.subscription_change_requests(status,effective_from);
create trigger subscription_plans_updated before update on public.subscription_plans for each row execute function app_private.set_updated_at();create trigger subscription_plan_items_updated before update on public.subscription_plan_items for each row execute function app_private.set_updated_at();create trigger subscriptions_updated before update on public.subscriptions for each row execute function app_private.set_updated_at();create trigger subscription_cycles_updated before update on public.subscription_cycles for each row execute function app_private.set_updated_at();

insert into public.app_settings(key,value,description,is_public) values('subscriptions.allocation_horizon_days','56','Días de capacidad protegida para Plan de Pan',false),('subscriptions.cycle_generation_days_ahead','35','Horizonte de generación de ciclos',false),('subscriptions.closure_policy','"manual_review"','Política ante cierres: manual_review por defecto',false) on conflict(key) do nothing;

create or replace function app_private.validate_subscription_plan() returns trigger language plpgsql set search_path='' as $$begin if new.status='active' and (new.stripe_product_id is null or new.stripe_price_id is null or not exists(select 1 from public.subscription_plan_items i join public.product_variants v on v.id=i.product_variant_id where i.subscription_plan_id=new.id and v.status='active')) then raise exception 'active_plan_incomplete' using errcode='23514';end if;return new;end$$;
create constraint trigger validate_subscription_plan after insert or update on public.subscription_plans deferrable initially deferred for each row execute function app_private.validate_subscription_plan();

create or replace function public.create_subscription_candidate(p_plan_id uuid,p_pickup_point_id uuid,p_weekday integer,p_window_id uuid default null)
returns table(ok boolean,reason text,subscription_id uuid,cycle_id uuid,collection_date date,stripe_price_id text) language plpgsql security definer set search_path='' as $$declare pl public.subscription_plans;s uuid;c uuid;d date;item record;av record;h integer;begin
 if auth.uid() is null then raise exception 'authentication_required' using errcode='42501';end if;if p_weekday not between 1 and 7 then return query select false,'invalid_weekday',null::uuid,null::uuid,null::date,null::text;return;end if;
 select * into pl from public.subscription_plans where id=p_plan_id and status='active' and is_public for update;if not found then return query select false,'plan_unavailable',null::uuid,null::uuid,null::date,null::text;return;end if;
 d:=current_date+((p_weekday-extract(isodow from current_date)::integer+7)%7);if d<=current_date then d:=d+7;end if;select (value#>>'{}')::integer into h from public.app_settings where key='subscriptions.allocation_horizon_days';h:=coalesce(h,56);
 for item in select i.*,v.status variant_status from public.subscription_plan_items i join public.product_variants v on v.id=i.product_variant_id where i.subscription_plan_id=pl.id order by i.product_variant_id loop perform pg_advisory_xact_lock(1,hashtext(item.product_variant_id::text||d::text));perform pg_advisory_xact_lock(2,hashtext(p_pickup_point_id::text||d::text));select * into av from app_private.variant_availability(item.product_variant_id,p_pickup_point_id,d);if item.variant_status<>'active' or not av.is_available or item.quantity>av.remaining then return query select false,'capacity_unavailable',null::uuid,null::uuid,d,null::text;return;end if;end loop;
 insert into public.subscriptions(customer_id,subscription_plan_id,pickup_point_id,preferred_weekday,preferred_collection_window_id,status,stripe_price_id,next_collection_date) values(auth.uid(),pl.id,p_pickup_point_id,p_weekday,p_window_id,'incomplete',pl.stripe_price_id,d) returning id into s;
 insert into public.subscription_items(subscription_id,product_variant_id,product_name_snapshot,variant_name_snapshot,quantity,unit_price_cents_snapshot,vat_rate_snapshot) select s,i.product_variant_id,p.name,v.name,i.quantity,coalesce(v.price_cents,0),v.vat_rate from public.subscription_plan_items i join public.product_variants v on v.id=i.product_variant_id join public.products p on p.id=v.product_id where i.subscription_plan_id=pl.id;
 insert into public.subscription_cycles(subscription_id,cycle_start,cycle_end,collection_date,status,capacity_reserved) values(s,d,d,d,'capacity_reserved',true) returning id into c;
 insert into public.subscription_capacity_allocations(product_variant_id,pickup_point_id,allocation_date,quantity,source_reference,subscription_cycle_id) select product_variant_id,p_pickup_point_id,d,quantity,s::text,c from public.subscription_items where subscription_id=s;
 insert into public.subscription_status_history(subscription_id,new_status,actor_id,source,reason) values(s,'incomplete',auth.uid(),'customer','subscription_candidate_created');return query select true,'incomplete',s,c,d,pl.stripe_price_id;
end$$;

create or replace function public.request_subscription_change(p_subscription_id uuid,p_type public.subscription_change_type,p_data jsonb,p_effective_from date) returns uuid language plpgsql security definer set search_path='' as $$declare id uuid;begin if not exists(select 1 from public.subscriptions where subscriptions.id=p_subscription_id and (customer_id=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin'))) then raise exception 'insufficient_privilege' using errcode='42501';end if;if p_effective_from<current_date then raise exception 'retroactive_change' using errcode='23514';end if;insert into public.subscription_change_requests(subscription_id,type,requested_data,effective_from,requested_by) values(p_subscription_id,p_type,coalesce(p_data,'{}'),p_effective_from,auth.uid()) returning subscription_change_requests.id into id;return id;end$$;

create or replace function public.process_subscription_invoice(p_event_id text,p_invoice_id text,p_stripe_subscription text,p_payment_intent text,p_amount integer,p_currency text,p_payload_hash text) returns table(ok boolean,reason text,order_id uuid) language plpgsql security definer set search_path='' as $$declare s public.subscriptions;c public.subscription_cycles;o uuid;code text;expected integer;begin if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501';end if;if exists(select 1 from public.payment_events where stripe_event_id=p_event_id) then select sc.order_id into o from public.subscription_cycles sc where sc.stripe_invoice_id=p_invoice_id;return query select true,'already_processed',o;return;end if;select * into s from public.subscriptions where stripe_subscription_id=p_stripe_subscription for update;if not found then insert into public.payment_events(stripe_event_id,event_type,payment_intent_id,processing_status,payload_hash,error_message,processed_at) values(p_event_id,'invoice.paid',p_payment_intent,'failed',p_payload_hash,'subscription_not_found',now());return query select false,'subscription_not_found',null::uuid;return;end if;select * into c from public.subscription_cycles where subscription_id=s.id and status in('capacity_reserved','invoiced','paid') order by collection_date limit 1 for update;if not found then update public.subscriptions set status='requires_attention',requires_attention_reason='paid_invoice_without_cycle' where id=s.id;return query select false,'cycle_not_found',null::uuid;return;end if;select p.price_cents into expected from public.subscription_plans p where p.id=s.subscription_plan_id;if upper(p_currency)<>'EUR' or p_amount<>expected then update public.subscriptions set status='requires_attention',requires_attention_reason='invoice_amount_mismatch' where id=s.id;return query select false,'amount_mismatch',null::uuid;return;end if;code:='FZ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));insert into public.orders(public_code,customer_id,pickup_point_id,collection_date,status,payment_status,total_cents,subtotal_cents,tax_cents,currency,confirmed_at,order_type,subscription_id,subscription_cycle_id) values(code,s.customer_id,s.pickup_point_id,c.collection_date,'confirmed','paid',p_amount,p_amount,0,'EUR',now(),'subscription',s.id,c.id) returning id into o;insert into public.order_items(order_id,product_id,product_variant_id,product_name_snapshot,variant_name_snapshot,approximate_weight_snapshot,unit_price_cents,vat_rate_snapshot,tax_cents,quantity,line_total_cents) select o,v.product_id,i.product_variant_id,i.product_name_snapshot,i.variant_name_snapshot,v.approximate_weight_grams,i.unit_price_cents_snapshot,i.vat_rate_snapshot,0,i.quantity,i.quantity*i.unit_price_cents_snapshot from public.subscription_items i join public.product_variants v on v.id=i.product_variant_id where i.subscription_id=s.id;update public.subscription_cycles set status='order_created',stripe_invoice_id=p_invoice_id,stripe_payment_intent_id=p_payment_intent,order_id=o where id=c.id;update public.subscriptions set status='active',requires_attention_reason=null where id=s.id;insert into public.payment_events(stripe_event_id,event_type,payment_intent_id,order_id,processing_status,payload_hash,processed_at) values(p_event_id,'invoice.paid',p_payment_intent,o,'processed',p_payload_hash,now());insert into public.subscription_status_history(subscription_id,previous_status,new_status,source,reason) values(s.id,s.status,'active','stripe_webhook','invoice.paid');return query select true,'order_created',o;end$$;

create or replace function public.run_subscription_jobs() returns jsonb language plpgsql security definer set search_path='' as $$declare expired_count integer;attention_count integer;begin if auth.role()<>'service_role' then raise exception 'service_role_required' using errcode='42501';end if;if not pg_try_advisory_xact_lock(8,240000) then return jsonb_build_object('skipped','concurrent_run');end if;with stale as(update public.subscriptions set status='cancelled',cancelled_at=now(),cancellation_reason='incomplete_expired' where status='incomplete' and created_at<now()-interval '1 hour' returning id) update public.subscription_cycles set status='cancelled',capacity_reserved=false,failure_reason='incomplete_expired' where subscription_id in(select id from stale) and status in('planned','capacity_reserved');get diagnostics expired_count=row_count;delete from public.subscription_capacity_allocations a using public.subscription_cycles c where a.subscription_cycle_id=c.id and c.status in('cancelled','skipped','failed');update public.subscriptions s set status='requires_attention',requires_attention_reason='inactive_subscription_product' where status in('active','trialing') and exists(select 1 from public.subscription_items i join public.product_variants v on v.id=i.product_variant_id where i.subscription_id=s.id and v.status<>'active');get diagnostics attention_count=row_count;update public.subscriptions s set status='requires_attention',requires_attention_reason='paid_cycle_without_order' where exists(select 1 from public.subscription_cycles c where c.subscription_id=s.id and c.status='paid' and c.order_id is null);insert into public.audit_logs(action,entity_type,new_data) values('subscriptions.jobs.completed','subscriptions',jsonb_build_object('expired',expired_count,'attention',attention_count));return jsonb_build_object('expired',expired_count,'attention',attention_count);end$$;

alter table public.subscription_plans enable row level security;alter table public.subscription_plan_items enable row level security;alter table public.subscriptions enable row level security;alter table public.subscription_items enable row level security;alter table public.subscription_cycles enable row level security;alter table public.subscription_status_history enable row level security;alter table public.subscription_change_requests enable row level security;
create policy plans_public_read on public.subscription_plans for select to anon,authenticated using(status='active' and is_public or app_private.has_role('owner') or app_private.has_role('admin') or app_private.has_role('operator'));create policy plan_items_public_read on public.subscription_plan_items for select to anon,authenticated using(exists(select 1 from public.subscription_plans p where p.id=subscription_plan_id and p.status='active' and p.is_public) or app_private.has_role('owner') or app_private.has_role('admin') or app_private.has_role('operator'));
create policy subscriptions_own_read on public.subscriptions for select to authenticated using(customer_id=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin') or app_private.has_role('operator'));create policy subscription_items_read on public.subscription_items for select to authenticated using(exists(select 1 from public.subscriptions s where s.id=subscription_id and(s.customer_id=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin') or app_private.has_role('operator'))));create policy cycles_read on public.subscription_cycles for select to authenticated using(exists(select 1 from public.subscriptions s where s.id=subscription_id and(s.customer_id=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin') or app_private.has_role('operator'))));create policy history_read on public.subscription_status_history for select to authenticated using(exists(select 1 from public.subscriptions s where s.id=subscription_id and(s.customer_id=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin'))));create policy changes_read on public.subscription_change_requests for select to authenticated using(requested_by=auth.uid() or app_private.has_role('owner') or app_private.has_role('admin'));
create policy plans_admin_manage on public.subscription_plans for all to authenticated using(app_private.has_role('owner') or app_private.has_role('admin')) with check(app_private.has_role('owner') or app_private.has_role('admin'));create policy plan_items_admin_manage on public.subscription_plan_items for all to authenticated using(app_private.has_role('owner') or app_private.has_role('admin')) with check(app_private.has_role('owner') or app_private.has_role('admin'));
grant select on public.subscription_plans,public.subscription_plan_items to anon,authenticated;grant select on public.subscriptions,public.subscription_items,public.subscription_cycles,public.subscription_status_history,public.subscription_change_requests to authenticated;grant insert,update,delete on public.subscription_plans,public.subscription_plan_items to authenticated;grant execute on function public.create_subscription_candidate(uuid,uuid,integer,uuid) to authenticated;grant execute on function public.request_subscription_change(uuid,public.subscription_change_type,jsonb,date) to authenticated;revoke all on function public.process_subscription_invoice(text,text,text,text,integer,text,text) from public;grant execute on function public.process_subscription_invoice(text,text,text,text,integer,text,text) to service_role;
